    rows.push({
      title: "",
      url: "",
      name: name,
      type: "button",
      action: action,
      style: { layout_flexGrow: 1, layout_flexBasisPercent: full ? 1 : 0.45 }
    });
  }
  function label(name) { button("—— " + name + " ——", "void 0;", true); }
  function toggle(name, enabled, action) {
    button((enabled ? "🟢 " : "⚪ ") + name, action, false);
  }

  label("含遇見賬號");
  button(state.readerToken ? "已登入：" + (state.username || state.tier || "賬號") : "開啟網頁登入 / 註冊", "YuJianOpenWebLogin();", true);
  button("同步登入狀態", "YuJianSyncLogin();", true);
