function check(key) {
  var v = "";
  try {
    if (typeof result !== "undefined" && result != null) {
      v = result.get ? result.get(key) : result[key];
    }
  } catch(e) {}
  v = String(v || "").trim();
  if (!v) {
    try { java.toast(key + " 空值未保存"); } catch(e) {}
    return;
  }
  try {
    var map = new Packages.java.util.HashMap();
    map.put(key, v);
    java.upLoginData(map);
  } catch(e1) {
    try {
      var obj = {};
      obj[key] = v;
      java.upLoginData(obj);
    } catch(e2) {}
  }
  try { java.toast(key + " 已保存"); } catch(e) {}
}

