function YuJianToggleValue(value, fallback) {
  var text = String(value === undefined || value === null ? "" : value).trim();
  if (!text) return fallback === true;
  return text === "ON" || text === "true" || text === "1";
}

function YuJianState(ctx) {
  var holder = YuJianSource(ctx);
  var state = {};
  try { state = JSON.parse(String((holder && holder.getVariable && holder.getVariable()) || "{}")); } catch (error) { state = {}; }
  if (!state || typeof state !== "object") state = {};
  var info = {};
  try { info = JSON.parse(String((holder && holder.getLoginInfo && holder.getLoginInfo()) || "{}")); } catch (error) { info = {}; }
  if (!info || typeof info !== "object") info = {};
  var savedToken = "";
  try {
    var loginHeaders = JSON.parse(String((holder && holder.getLoginHeader && holder.getLoginHeader()) || "{}"));
    savedToken = String((loginHeaders && loginHeaders["X-Reader-Token"]) || "");
  } catch (error) {}
  if (!savedToken) savedToken = String(info.readerToken || state.readerToken || "");
  if (!savedToken && holder && holder.get) {
    try { savedToken = String(holder.get("readerToken") || ""); } catch (error) {}
  }
  state.readerToken = savedToken;
  state.username = String(info.username || state.username || "");
  state.tier = String(info.tier || state.tier || "");
  state.comments = YuJianToggleValue(info.comments, state.comments === true);
  state.titleComments = YuJianToggleValue(info.titleComments, state.titleComments === true);
  state.chapterReview = YuJianToggleValue(info.chapterReview, state.chapterReview === true);
  state.authorSay = YuJianToggleValue(info.authorSay, state.authorSay === true);
  state.large = YuJianToggleValue(info.large, state.large === true);
  delete state.qdCookie;
  delete state.qdLogin;
  delete state.loginStatus;
  return state;
}

function YuJianLoginState() {
  return YuJianState(arguments.length > 0 ? arguments[0] : null);
}

function YuJianPersist(state) {
  var holder = YuJianSource(null);
  if (!holder) return false;
  var value = JSON.stringify(state);
  var token = String(state.readerToken || "");
  var variableSaved = false;
  var cacheSaved = false;
  try { holder.setVariable(value); } catch (error) {}
  try { if (holder.putVariable) holder.putVariable(value); } catch (error) {}
  try { if (holder.put) holder.put("readerToken", token); } catch (error) {}
  try { variableSaved = String(holder.getVariable ? holder.getVariable() : "") === value; } catch (error) {}
  try { cacheSaved = !holder.get || String(holder.get("readerToken") || "") === token; } catch (error) {}
  return variableSaved || cacheSaved;
}





function YuJianGetCookie(url) {
  var value = "";
  try {
    var cm = android.webkit.CookieManager.getInstance();
    value = String(cm.getCookie(url) || "");
  } catch (e) {
    try {
      var cm2 = Packages.android.webkit.CookieManager.getInstance();
      value = String(cm2.getCookie(url) || "");
    } catch (e2) {}
  }
  if (!value) {
    try { value = String(cookie.getCookie(url) || ""); } catch (e) {}
  }
  return value;
}

function YuJianExtractToken(url) {
  var ck = YuJianGetCookie(url);
  var match = ck.match(/(?:^|;\s*)reader\.token=([^;]+)/);
  if (match) return decodeURIComponent(match[1].replace(/^\s+|\s+$/g, ""));
  return "";
}

function YuJianHeaders(ctx, state) {
  state = state || YuJianLoginState();
  var headers = { Accept: "application/json" };
  var token = String(state.readerToken || "");
  if (token) headers["X-Reader-Token"] = token;
  return headers;
}

function YuJianLoginSave(state) {
  var persisted = YuJianPersist(state);
  var headers = YuJianHeaders(null, state);
  var holder = YuJianSource(null);
  var headerSaved = false;
  var loginInfoSaved = false;
  if (holder) {
    try {
      if (headers["X-Reader-Token"]) holder.putLoginHeader(JSON.stringify(headers));
      else holder.removeLoginHeader();
      headerSaved = true;
    } catch (error) {}
  }
  try {
    var info = {};
    if (!holder) info = YuJianUiState();
    else {
      try { info = JSON.parse(holder.getLoginInfo() || "{}"); } catch (error) { info = {}; }
      if (!info || typeof info !== "object") info = {};
    }
    info.username = state.username;
    info.tier = state.tier;
    info.readerToken = state.readerToken;
    info.comments = state.comments ? "ON" : "OFF";
    info.titleComments = state.titleComments ? "ON" : "OFF";
    info.chapterReview = state.chapterReview ? "ON" : "OFF";
    info.authorSay = state.authorSay ? "ON" : "OFF";
    info.large = state.large ? "ON" : "OFF";
    if (holder) holder.putLoginInfo(JSON.stringify(info));
    loginInfoSaved = true;
    java.upLoginData({ username: state.username, tier: state.tier, readerToken: state.readerToken });
  } catch (error) {}
  try { java.reLoginView(); } catch (error) {}
  return persisted || headerSaved || loginInfoSaved || YuJianSavedTokenMatches(holder, state.readerToken);
}


function YuJianSavedTokenMatches(holder, token) {
  token = String(token || "");
  var variableToken = "";
  var cacheToken = "";
  var headerToken = "";
  try {
    var variableState = JSON.parse(String((holder && holder.getVariable && holder.getVariable()) || "{}"));
    variableToken = String((variableState && variableState.readerToken) || "");
  } catch (error) {}
  try {
    if (holder && holder.get) cacheToken = String(holder.get("readerToken") || "");
  } catch (error) {}
  try {
    if (holder && holder.getLoginHeader) {
      var loginHeaders = {};
      try { loginHeaders = JSON.parse(String(holder.getLoginHeader() || "{}")); } catch (error) { loginHeaders = {}; }
      headerToken = String((loginHeaders && loginHeaders["X-Reader-Token"]) || "");
    }
  } catch (error) {}
  return variableToken === token || cacheToken === token || headerToken === token;
}





function YuJianOpenWebLogin() {
  try {
