function YuJianSyncLogin() {
  try {
    var cm = android.webkit.CookieManager.getInstance();
    if (cm.flush) cm.flush();
  } catch (e) {
    try {
      var cm2 = Packages.android.webkit.CookieManager.getInstance();
      if (cm2.flush) cm2.flush();
    } catch (e2) {}
  }
  var token = YuJianExtractToken("http://210.16.175.40:11451");
  var state = YuJianLoginState();
  if (!token) {
    try { java.ajax("http://210.16.175.40:11451/?login=1&t=" + Date.now()); } catch (error) {}
    token = YuJianExtractToken("http://210.16.175.40:11451");
  }
  if (!token) {
    java.toast("尚未檢測到登入憑證，請先在網頁中登入後再點擊同步");
    return;
  }
  var options = {
    method: "GET",
    headers: {
      "Accept": "application/json",
      "X-Reader-Token": token
    }
  };
  try {
    var resp = java.ajax("http://210.16.175.40:11451/reader/me," + JSON.stringify(options));
    var me = JSON.parse(String(resp || "{}"));
    if (!me || !me.username) {
      state.readerToken = "";
      state.username = "";
      state.tier = "";
      YuJianLoginSave(state);
      java.toast("憑證檢驗失敗或已過期，請重新登入");
      return;
    }
    state.readerToken = token;
    state.username = String(me.username || "");
    state.tier = String((me.tier && (me.tier.name || me.tier.code)) || "");
    if (!YuJianLoginSave(state)) {
      java.toast("登入狀態保存失敗，請重新進入登入介面後再試");
      return;
    }
    java.toast("已成功同步賬號：" + state.username + (state.tier ? " (" + state.tier + ")" : ""));
  } catch (error) {
    java.toast("同步失敗：" + String((error && error.message) || error));
  }
}

