function YuJianLogout() {
  var state = YuJianLoginState();
  try {
    if (state.readerToken) {
      var options = { method: "POST", headers: { "Content-Type": "application/json", "X-Reader-Token": state.readerToken } };
      java.ajax("http://210.16.175.40:11451/reader/logout," + JSON.stringify(options));
    }
  } catch (error) {}
  try { cookie.removeCookie("http://210.16.175.40:11451"); } catch (error) {}
  try {
    var cm = android.webkit.CookieManager.getInstance();
    cm.setCookie("http://210.16.175.40:11451/", "reader.token=; Max-Age=0");
    cm.flush();
  } catch (e) {
    try {
      var cm2 = Packages.android.webkit.CookieManager.getInstance();
      cm2.setCookie("http://210.16.175.40:11451/", "reader.token=; Max-Age=0");
      cm2.flush();
    } catch (e2) {}
  }
  var holder = YuJianSource(null);
  try { if (holder) holder.removeLoginHeader(); } catch (error) {}
  state.readerToken = "";
  state.username = "";
  state.tier = "";
  YuJianLoginSave(state);
  java.toast(!YuJianState(null).readerToken ? "已退出含遇見賬號" : "退出清理失敗，請重試退出登入");
}

