function YuJianDetailInit(result) {
  var response = YuJianParseResult(result);
  if (Number(response.Result) !== 0) throw new Error(response.Message || '書籍詳情請求失敗');
  if (Number(response.Data.IsEpubSupportSplit) === 1) throw new Error('EPUB 書籍不支援書源正文');
  return response;
}

function YuJianTocInit(result) {
  var response = YuJianParseResult(result);
  if (Number(response.Result) !== 0) throw new Error(response.Message || '目錄請求失敗');
  var data = response.Data || {};
  var epubKeys = ['IsEpubSupportSplit', 'IsEpub', 'isEpub', 'Epub', 'epub', 'SplitEpub'];
  for (var index = 0; index < epubKeys.length; index++) {
    var value = data[epubKeys[index]];
    if (Number(value) === 1 || String(value).toLowerCase() === 'true') {
      throw new Error('EPUB 書籍不支援書源正文');
    }
  }
  var chapters = data.Chapters || [];
  var markers = ['版權頁', '版权页', '封面頁', '封面页', '目錄頁', '目录页', 'epub'];
  var hits = 0;
  for (var itemIndex = 0; itemIndex < chapters.length && itemIndex < 30; itemIndex++) {
    var title = String((chapters[itemIndex] || {}).N || '').toLowerCase();
    for (var markerIndex = 0; markerIndex < markers.length; markerIndex++) {
      if (title.indexOf(markers[markerIndex].toLowerCase()) >= 0) {
        hits++;
        break;
      }
    }
  }
  if (chapters.length && hits >= Math.min(2, chapters.length)) {
    throw new Error('EPUB 書籍不支援書源正文');
  }
  return response;
}

function YuJianChapterInfo(result) {
  var item = result || {};
  var words = Number(item.W || 0);
  var timestamp = Number(item.T || item.DisplayTime || 0);
  if (timestamp > 0 && timestamp < 100000000000) timestamp *= 1000;
  var date = timestamp ? new Date(timestamp) : null;
  var time = '';
  if (date && !isNaN(date.getTime())) {
    function fixed(value) { return (value < 10 ? '0' : '') + value; }
    time = date.getFullYear() + '-' + fixed(date.getMonth() + 1) + '-' + fixed(date.getDate()) +
      ' ' + fixed(date.getHours()) + ':' + fixed(date.getMinutes());
  }
  var isCached = Number(item.iscache || item.is_cached || item.isCache || 0) === 1;
  var mark = isCached ? '🍊 ' : '';
  return mark + (words ? words + '字' : '') + (time ? (words ? ' ' : '') + time : '');
}

function YuJianCommentContext(baseUrl, chapter) {
  var ids = YuJianIdsFromUrl(baseUrl);
  if (ids.bookId && ids.chapterId) return ids;
  try {
    var url = String((chapter && (chapter.url || chapter.href)) || '');
    var fromChapter = YuJianIdsFromUrl(url);
    if (fromChapter.bookId && fromChapter.chapterId) return fromChapter;
  } catch (error) {}
  return ids;
}

function YuJianContent(result, baseUrl, chapter) {
  var ctx = this || {};
  var response = YuJianParseResult(result);
  if (response.detail) throw new Error(response.detail);
  if (response.message && !response.content) throw new Error(response.message);
  var content = String(response.content || '');
  if (!content) throw new Error('正文內容為空');
  var state = YuJianState(ctx);
  if (!state.comments) {
    return YuJianCleanText(content.replace(/<img\b[^>]*YuJianComment:[^>]*>/gi, ''));
  }
  var ids = {
    bookId: String(response.bookId || response.book_id || ''),
    chapterId: String(response.chapterId || response.chapter_id || '')
  };
  if (!ids.bookId || !ids.chapterId) ids = YuJianCommentContext(baseUrl, chapter);
  var contextUrl = YuJianApiUrl('/book-content', ids);
  return YuJianInjectComments(ctx, content, contextUrl);
}

function YuJianIdsFromUrl(baseUrl) {
  var value = String(baseUrl || '');
  function query(name) {
    var match = value.match(new RegExp('[?&]' + name + '=([^&#]+)'));
    return match ? decodeURIComponent(match[1].replace(/\+/g, ' ')) : '';
  }
  return { bookId: query('bookId'), chapterId: query('chapterId') };
}

function YuJianCleanText(value) {
  var images = [];
  var text = String(value || '').replace(/<img\b[^>]*>/gi, function(tag) {
    images.push(tag);
    return '\n@@YuJianImg' + (images.length - 1) + '@@\n';
  });
  text = text
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/\r\n?/g, '\n');
  return text.replace(/@@YuJianImg(\d+)@@/g, function(all, index) {
    return images[Number(index)] || '';
  });
}

function YuJianSecondColor(hex, ment) {
  if (!hex) return '232323';
  ment = ment || 40;
  var str = String(hex).replace(/^#/, '');
  if (str.length < 6) return '232323';
  var r = parseInt(str.slice(-6, -4), 16);
  var g = parseInt(str.slice(-4, -2), 16);
  var b = parseInt(str.slice(-2), 16);
  if (isNaN(r) || isNaN(g) || isNaN(b)) return '232323';
  var brightness = (r * 299 + g * 587 + b * 114) / 1000;
  var nr, ng, nb;
  if (brightness > 128) {
    nr = Math.max(0, r - ment);
    ng = Math.max(0, g - ment);
    nb = Math.max(0, b - ment);
  } else {
    nr = Math.min(255, r + ment);
    ng = Math.min(255, g + ment);
    nb = Math.min(255, b + ment);
  }
  return ((1 << 24) + (nr << 16) + (ng << 8) + nb).toString(16).slice(1);
}

function YuJianColor(ctx, needBg) {
  var bridge = YuJianBridge(ctx);
  var tc = '101010', ac = 'D25A28', bg = 'EFEFEF';
  if (!bridge) return [tc, ac, bg];
  try {
    var rdc = bridge.getReadBookConfigMap ? bridge.getReadBookConfigMap() : null;
    var md = bridge.getThemeMode ? bridge.getThemeMode() : 1;
    if (md === 0 && bridge.getThemeConfigMap) {
      var tm = bridge.getThemeConfigMap();
      md = tm && tm['isNightTheme'] ? 2 : 1;
    }
    if (rdc) {
      if (md === 3) {
        if (rdc['textColorEInk']) tc = String(rdc['textColorEInk']).slice(-6);
        if (rdc['textAccentColorEInk']) ac = String(rdc['textAccentColorEInk']).slice(-6);
        if (needBg && rdc['bgStrEInk']) bg = YuJianSecondColor(rdc['bgStrEInk']);
      } else if (md === 2) {
        if (rdc['textColorNight']) tc = String(rdc['textColorNight']).slice(-6);
        if (rdc['textAccentColorNight']) ac = String(rdc['textAccentColorNight']).slice(-6);
        if (needBg && rdc['bgStrNight']) bg = YuJianSecondColor(rdc['bgStrNight']);
      } else {
        if (rdc['textColor']) tc = String(rdc['textColor']).slice(-6);
        if (rdc['textAccentColor']) ac = String(rdc['textAccentColor']).slice(-6);
        if (needBg && rdc['bgStr']) bg = YuJianSecondColor(rdc['bgStr']);
      }
    }
  } catch (e) {}
  return [tc, ac, bg];
}

function YuJianEscapeXml(text) {
  return String(text || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function YuJianWrapLines(text, maxChars) {
  var lines = [];
  var raw = String(text || '').split(/\r?\n/);
  for (var i = 0; i < raw.length; i++) {
    var line = raw[i].replace(/^\s+|\s+$/g, '');
    if (!line) continue;
    while (line.length > maxChars) {
      lines.push(line.slice(0, maxChars));
      line = line.slice(maxChars);
    }
    if (line.length > 0) lines.push(line);
  }
  return lines;
}

function YuJianSvgImage(encoded, options) {
  options = options || {};
  if (options.click) {
    var click = String(options.click).replace(/"/g, '\"');
    return '<img src="data:image/svg+xml;base64,' + encoded + ',{\"click\":\"' + click + '\",\"type\":\"img\",\"style\":\"' + String(options.style || 'full') + '\"}">';
  }
  return '<img src="data:image/svg+xml;base64,' + encoded + ',' + JSON.stringify(options) + '">';
}

// 模拟设备随机注册生成 qimei 与设备名
function YuJianRegisterDevice(ctx) {
  var bridge = YuJianBridge(ctx);
  var cache = (ctx && ctx.cache) || (typeof cache !== 'undefined' ? cache : null);
  var pp = ['realme', 'OPPO', 'Xiaomi', 'vivo', 'HUAWEI', 'samsung', 'Google', 'HONOR'];
  var ppl = ['RMX3366', 'PHY120', '24030PN60C', 'V2324A', 'ALN-AL10', 'SM-S9280', 'Pixel 4 XL', 'MAA-AN10'];
  var sjs = Math.floor(Math.random() * pp.length);
  var sj1 = Math.floor(Math.random() * 1001) + 1000;
  var sj2 = ppl[sjs];
  var sj3 = pp[sjs];
  var tm = '';
  try {
    tm = bridge && bridge.timeFormatUTC ? bridge.timeFormatUTC(Date.now(), 'yyyyMMddHHmmsss', 28800000) : String(Date.now());
  } catch (e) {
    tm = String(Date.now());
  }
  var hex = '0123456789abcdef';
  var digits = '0123456789';
  var mac = '';
  for (var i = 0; i < 6; i++) {
    if (i > 0) mac += ':';
    mac += hex[Math.floor(Math.random() * hex.length)] + hex[Math.floor(Math.random() * hex.length)];
  }
  for (var k = 0; k < 6; k++) {
    mac += digits[Math.floor(Math.random() * digits.length)];
  }
  var qimei = tm + mac;
  var devStr = String([sj1, sj2, sj3, qimei]);
  if (cache && cache.put) cache.put('yujian_device', devStr);
  return devStr;
}

// 本地 QDSign2 算法：生成 QDSign 与 QDInfo 签名直连起点接口
function YuJianQDSign(path, params, ctx) {
  var bridge = YuJianBridge(ctx);
  var cache = (ctx && ctx.cache) || (typeof cache !== 'undefined' ? cache : null);
  var devStr = cache && cache.get ? cache.get('yujian_device') : '';
  if (!devStr) devStr = YuJianRegisterDevice(ctx);
  var parts = String(devStr).split(',');
  var sj1 = parts[0], sj2 = parts[1], sj3 = parts[2], qimei = parts[3];
  var uid = '0';
  var pArr = typeof params === 'string' ? params.split('&') : (params || []);
  var sortedParams = pArr.slice().sort().join('&');
  var time = Date.now().toString();

  var sKey = '{1dYgqE)h9,R)hKqEcv4]k[h';
  var sIv = '01234567';
  var signRaw = 'Rv1rPTnczce|' + time + '|' + uid + '|' + qimei + '||||' + bridge.md5Encode(sortedParams.toLowerCase()) + '|f189adc92b816b3e9da29ea304d4a7e4';
  var sign = bridge.tripleDESEncodeBase64Str(signRaw, sKey, 'CBC', 'PKCS5Padding', sIv);

  var iKey = '0821CAAD409B84020821CAAD';
  var iIv = bridge.base64Decode('AAAAAAAAAAA=');
  var infoRaw = qimei + '|7.9.378|1080|1184|1000009|10|1|' + sj2 + '|1436|1000009|4|' + uid + '|' + time + '|1|' + qimei + '|||||0';
  var info = bridge.tripleDESEncodeBase64Str(infoRaw, iKey, 'CBC', 'PKCS5Padding', iIv);

  var headers = {
    'QDSign': sign,
    'QDInfo': info,
    'tstamp': time,
    'User-Agent': 'Mozilla/mobile QDReaderAndroid/7.9.378/1436/1000009/' + sj3
  };
  return 'https://druidv6.if.qidian.com/argus/api/' + path + '?' + sortedParams + ',' + JSON.stringify({ headers: headers });
}

// 本地直接请求起点获取本章说/段评摘要与作家说
function YuJianLocalReviewSummary(ctx, bookId, chapterId) {
  var bridge = YuJianBridge(ctx);
  var result = { counts: {}, chapter: 0, authorName: '', authorComments: '', authorSay: {}, endComments: [] };
  if (!bridge || !bookId || !chapterId) return result;

  var param = 'bookId=' + encodeURIComponent(String(bookId)) + '&chapterId=' + encodeURIComponent(String(chapterId));
  var activityUrl = YuJianQDSign('v1/assembly/getchapteractivity', param, ctx);
  var summaryUrl = YuJianQDSign('v1/chapterreview/getchapterrepagesummary', param + '&useImei=0&strategy=3', ctx);
  var endReviewUrl = YuJianQDSign('v1/chapterreview/getchapterendchapterreview', param + '&pg=1&pz=20', ctx);

  var res = [];
  try {
    if (bridge.ajaxAll) res = bridge.ajaxAll([activityUrl, summaryUrl, endReviewUrl]);
    else res = [bridge.ajax(activityUrl), bridge.ajax(summaryUrl), bridge.ajax(endReviewUrl)];
  } catch (e) {
    try { res = [bridge.ajax(activityUrl), bridge.ajax(summaryUrl)]; } catch (e2) {}
  }

  // 1. 解析段评数量汇总
  try {
    var rawSum = res[1] ? (typeof res[1].body === 'function' ? res[1].body() : res[1]) : '{}';
    var sumObj = JSON.parse(String(rawSum || '{}')).Data || {};
    var list = (sumObj.Getparagraphscommentcounts || {}).DataList || [];
    for (var i = 0; i < list.length; i++) {
      var item = list[i];
      var pid = Number(item.ParagraphId);
      var cnt = Number(item.CommentCount || item.TextCount || 0);
      if (pid === -1) {
        result.chapter = cnt;
      } else if (pid > 0 && cnt > 0) {
        result.counts[String(pid)] = { count: cnt, hot: Boolean(item.HasHotComment) };
      }
    }
  } catch (errSum) {}

  // 2. 解析作家说与末尾评论
  try {
    var rawAct = res[0] ? (typeof res[0].body === 'function' ? res[0].body() : res[0]) : '{}';
    var actObj = JSON.parse(String(rawAct || '{}')).Data || {};
    var actData = actObj.Getchapteractivity || {};
    result.authorSay = actData;
    result.authorName = String(actData.AuthorName || '');
    result.authorComments = String(actData.AuthorComments || '');

    var endCommentsObj = actObj.Getchapterendcomments || {};
    var endList = endCommentsObj.DataList || [];
    if (endCommentsObj.TotalCount && !result.chapter) result.chapter = Number(endCommentsObj.TotalCount);

    for (var k = 0; k < endList.length && k < 5; k++) {
      var c = endList[k];
      var txt = String(c.Content || '').replace(/https?:\/\/[^\s]+/g, '').replace(/["']/g, '');
      result.endComments.push({
        nickname: String(c.UserName || '書友'),
        content: txt,
        likeCount: Number(c.AgreeAmount || 0)
      });
    }
  } catch (errAct) {}

  // 3. 校验末尾章评数
  try {
    if (res[2]) {
      var rawEnd = typeof res[2].body === 'function' ? res[2].body() : res[2];
      var endData = JSON.parse(String(rawEnd || '{}')).Data || {};
      if (endData.TotalCount !== undefined) result.chapter = Number(endData.TotalCount);
    }
  } catch (errEnd) {}

  return result;
}

// 降级使用服务端评论摘要接口
function YuJianServerReviewSummary(ctx, baseUrl) {
  var ids = YuJianIdsFromUrl(baseUrl);
  var result = { counts: {}, chapter: 0, authorName: '', authorComments: '', endComments: [] };
  if (!ids.bookId || !ids.chapterId) return result;
  var bridge = YuJianBridge(ctx);
  if (!bridge) return result;
  var token = YuJianCurrentToken(ctx, YuJianState(ctx));
  var options = YuJianRequestOptions(null, token);
  var url = YuJianApiUrl('/reviews/summary', ids) + ',' + JSON.stringify(options);
  try {
    var body = bridge.ajax(url);
    var resp = JSON.parse(String(body || '{}'));
    var data = resp.data || resp.Data || {};
    var paras = data.paragraphs || [];
    for (var i = 0; i < paras.length; i++) {
      var p = paras[i];
      var pid = Number(p.paragraphId);
      var cnt = Number(p.count || 0);
      if (pid === -1) {
        result.chapter = cnt;
      } else if (pid > 0 && cnt > 0) {
        result.counts[String(pid)] = { count: cnt, hot: Boolean(p.isHot) };
      }
    }
    var act = data.authorActivity || {};
    if (act.authorName || act.content) {
      result.authorName = String(act.authorName || '');
      result.authorComments = String(act.content || '');
    }
  } catch (err) {
    try {
      var fallbackUrl = YuJianApiUrl('/source/comments/counts', ids) + ',' + JSON.stringify(options);
      var fbBody = bridge.ajax(fallbackUrl);
      var fbResp = JSON.parse(String(fbBody || '{}'));
      result.counts = fbResp.counts || {};
      result.chapter = Number(fbResp.chapter || 0);
    } catch (fbErr) {}
  }
  return result;
}

// 综合获取：本地算法优先，异常降级至服务端接口
function YuJianReviewSummary(ctx, baseUrl) {
  var ids = YuJianIdsFromUrl(baseUrl);
  try {
    var localRes = YuJianLocalReviewSummary(ctx, ids.bookId, ids.chapterId);
    if (localRes && (localRes.chapter > 0 || Object.keys(localRes.counts).length > 0 || localRes.authorComments)) {
      return localRes;
    }
  } catch (localErr) {}
  return YuJianServerReviewSummary(ctx, baseUrl);
}

