    '<text x="' + (width - right) + '" y="' + (y + 75) + '" font-size="36" text-anchor="end" font-family="' + font + '" fill="#000">' + YuJianEscapeXml(String(totalComments)) + '條評論 ❯</text>';
  y += titleHeight;

  var zanPath = '<path d="M8.74999 1.66699C8.43435 1.66699 8.14579 1.84533 8.00463 2.12765C7.84178 2.45336 7.74456 2.91228 7.66084 3.31295C7.64604 3.38376 7.63112 3.45605 7.61588 3.52984C7.5347 3.92296 7.44465 4.35908 7.31865 4.84207C7.08137 5.75168 6.72257 6.80035 6.09535 7.87401C5.9253 8.1651 5.60793 8.33334 5.27081 8.33342L4.99975 8.33348C3.61915 8.33363 2.50003 9.45287 2.50003 10.8335L2.5 14.9997C2.49999 16.3805 3.61928 17.4998 5 17.4998H6.21903C6.22936 17.5001 6.23972 17.5003 6.25009 17.5003L13.9618 17.5003C15.212 17.5003 16.27 16.5768 16.4389 15.3381L17.2344 10.3381C17.4391 8.83703 16.2723 7.50033 14.7573 7.50033H12.5V5.41699C12.5 3.96187 11.9992 2.95333 11.164 2.34684C10.3796 1.77734 9.43844 1.66699 8.74999 1.66699ZM9.29227 3.65384C9.3139 3.55032 9.33363 3.45901 9.35173 3.37858C9.67046 3.43048 9.9576 3.53059 10.1847 3.69548C10.4971 3.92232 10.8333 4.37212 10.8333 5.41699V8.33366C10.8333 8.7939 11.2064 9.16699 11.6667 9.16699H14.7573C15.2623 9.16699 15.6512 9.61256 15.583 10.1129L14.7875 15.1129C14.7312 15.5258 14.3786 15.8337 13.9618 15.8337L7.08343 15.8337V9.42884C8.09998 7.93645 8.61855 6.46187 8.93135 5.26275C9.06916 4.73449 9.1687 4.25197 9.2498 3.85889C9.26452 3.7875 9.27864 3.71907 9.29227 3.65384ZM4.99994 10.0001L5.41672 10L5.41666 15.8331H5C4.53976 15.8331 4.16666 15.46 4.16667 14.9998L4.16669 10.8335C4.1667 10.3733 4.53974 10.0002 4.99994 10.0001Z"/>';

  for (var index = 0; index < topReviews.length; index++) {
    var review = topReviews[index];
    if (!review) continue;
    var like = Number(review.likeCount || 0);
    var max = Math.floor((width - left - right) / contentSize);
    var lines = [];
    var text = YuJianFormatEmoji(String(review.content || ''));
    while (text) {
      lines.push(text.slice(0, max));
      text = text.slice(max);
    }
    var needEllipsis = lines.length > 4;
    lines = lines.slice(0, 4);
    if (needEllipsis && lines.length > 0) lines[lines.length - 1] = lines[lines.length - 1].slice(0, max - 1) + '…';

    var likeSize = 38, padding = 18, baseY = y + 40;
    var ascent = likeSize * 0.75, descent = likeSize * 0.25;
    var likeWidth = String(like).length * likeSize * 0.65;
    var pillWidth = iconSize + likeWidth + padding * 2;
    var pillX = width - right - pillWidth;
    var pillY = baseY - ascent - padding / 2;
    var pillHeight = ascent + descent + padding;

    svg += '<rect x="' + pillX + '" y="' + pillY + '" width="' + pillWidth + '" height="' + pillHeight + '" rx="25" fill="rgba(200,200,200,0.35)"/>';
    svg += '<text x="' + left + '" y="' + baseY + '" font-weight="bold" font-size="' + userSize + '" font-family="' + font + '" fill="#000">' + YuJianEscapeXml(review.nickname || '匿名用戶') + '</text>';
    var centerY = pillY + pillHeight / 2;
    var iconX = pillX + padding;
    var iconY = centerY - iconSize / 2;
    svg += '<g transform="translate(' + iconX + ',' + iconY + ') scale(' + (iconSize / 20) + ')" fill="#000">' + zanPath + '</g>';
    svg += '<text x="' + (iconX + iconSize) + '" y="' + (centerY + likeSize * 0.35) + '" font-size="' + likeSize + '" font-family="' + font + '" fill="#000">' + YuJianEscapeXml(String(like)) + '</text>';

