      lineY += lineHeight;
    }
    y += userSize + lineHeight * lines.length + spacing * 2.5;
  }

  var svgText = '<svg width="' + width + '" height="' + y + '" viewBox="0 0 ' + width + ' ' + y + '" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg"><rect x="2" y="2" width="' + (width - 4) + '" height="' + (y - 4) + '" fill="rgba(255,255,255,0.25)" rx="' + (corner - 1) + '" stroke="#888" stroke-width="1"/>' + svg + '</svg>';
  return YuJianSvgImage(String(bridge.base64Encode(svgText) || ''), {
    click: 'YuJianShowCmt(' + String(bookId) + ',' + String(chapterId) + ',null)',
    type: 'img',
    marker: 'YuJianChapterSay:' + bookId + ':' + chapterId,
    style: 'full'
  });
}

function YuJianBubbleTemplate(ctx) {
  try {
    var options = YuJianRequestOptions(null, YuJianCurrentToken(ctx, YuJianState(ctx)));
    var svg = String(YuJianBridge(ctx).ajax(YuJianApiUrl('/bubbles/api/get-bubble', { keep_number: true }) + ',' + JSON.stringify(options)) || '');
    if (svg.indexOf('<svg') >= 0) return svg;
  } catch (error) {}
  return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="5 14 45 36" width="180" height="144"><path d="M44 48 Q48 48 48 44 L48 20 Q48 16 44 16 L20 16 Q16 16 16 20 L16 24 S16 28 10 30 Q6 32 10 34 Q16 36 16 38 L16 44 Q16 48 20 48 Z" fill="none" stroke="#666666" stroke-width="0.7"/><text x="32" y="36.5" text-anchor="middle" font-family="system-ui,-apple-system,Arial,sans-serif" font-weight="600" font-size="11" fill="#666666">{n}</text></svg>';
}

function YuJianCommentBubble(ctx, data, bookId, chapterId, paragraphId, template) {
  var bridge = YuJianBridge(ctx);
  if (!bridge || !bridge.base64Encode) return '';
  template = String(template || YuJianBubbleTemplate(ctx) || '');
  if (!template) return '';
  var count = Number(data.count || 0);
  var display = count > 99 ? '99+' : String(count);
  var svg = template.replace(/\{n\}/g, display).replace(/\{N\}/g, display);
  var encoded = String(bridge.base64Encode(svg) || '');
  var state = YuJianState(ctx);
  var options = {
    style: state.large ? 'TEXT' : 'text',
    type: 'img',
    click: 'YuJianShowCmt(this, ' + String(bookId) + ',' + String(chapterId) + ',' + String(paragraphId) + ')',
    marker: 'YuJianComment:' + bookId + ':' + chapterId + ':' + paragraphId
  };
  return '<img src="data:image/svg+xml;base64,' + encoded + ',' + JSON.stringify(options) + '">';
}

function YuJianTitleBubble(ctx, count, bookId, chapterId, template) {
  var bridge = YuJianBridge(ctx);
  if (!bridge || !bridge.base64Encode) return '';
  template = String(template || YuJianBubbleTemplate(ctx) || '');
  if (!template) return '';
  var cnt = Number(count || 0);
  var display = cnt > 99 ? '99+' : String(cnt);
  var svg = template.replace(/\{n\}/g, display).replace(/\{N\}/g, display);
  var encoded = String(bridge.base64Encode(svg) || '');
  var state = YuJianState(ctx);
  var options = {
    style: state.large ? 'TEXT' : 'text',
    type: 'img',
    click: 'YuJianShowCmt(this, ' + String(bookId) + ',' + String(chapterId) + ',0)',
    marker: 'YuJianComment:' + bookId + ':' + chapterId + ':0'
  };
  return 'data:image/svg+xml;base64,' + encoded + ',' + JSON.stringify(options);
}
function YuJianClearTitleImage(chapterObj) {
  try {
    if (chapterObj && chapterObj.putImgUrl) chapterObj.putImgUrl('');
    else if (chapterObj) chapterObj.imgUrl = '';
  } catch (error) {}
}

function YuJianTitle(titleVal, baseUrlVal, chapterObj) {
  var ctx = this || {};
  var t = '';
  if (typeof titleVal !== 'undefined' && titleVal !== null) t = String(titleVal);
  else if (typeof title !== 'undefined' && title !== null) t = String(title);
  else if (typeof result !== 'undefined' && result !== null) t = String(result);
  else if (chapterObj && chapterObj.title) t = String(chapterObj.title);

  t = t.replace(/(?:data|https?):[\s\S]+$/, '').trim();
  var state = YuJianState(ctx);
  if (!state.comments || !state.titleComments) {
    YuJianClearTitleImage(chapterObj || (typeof chapter !== 'undefined' ? chapter : null));
    return t;
  }
  var u = String(baseUrlVal || (typeof baseUrl !== 'undefined' ? baseUrl : '') || '');
  var ids = YuJianIdsFromUrl(u);
  var ch = chapterObj || (typeof chapter !== 'undefined' ? chapter : null);
  var cid = ids.chapterId || (ch && (ch.chapterId || ch.variable || ch.cId)) || '';
  var bubble = '';
  try {
    var src = YuJianSource(ctx);
    if (src && src.get && cid) bubble = String(src.get(String(cid)) || '');
  } catch (e) {}

  if (!bubble && ids.bookId && ids.chapterId) {
    try {
      var summary = YuJianReviewSummary(ctx, u);
      var template = YuJianBubbleTemplate(ctx);
      if (summary && summary.chapter > 0 && template) {
        bubble = YuJianTitleBubble(ctx, summary.chapter, ids.bookId, ids.chapterId, template);
        var src2 = YuJianSource(ctx);
        if (src2 && src2.put) src2.put(String(ids.chapterId), bubble);
      }
    } catch (e2) {}
  }
  return t + (bubble ? bubble : '');
}

function YuJianInjectComments(ctx, content, baseUrl, chapterObj) {
  try {
    var summary = YuJianReviewSummary(ctx, baseUrl);
    var template = YuJianBubbleTemplate(ctx);
    var ids = YuJianIdsFromUrl(baseUrl);
    var state = YuJianState(ctx);
    var lines = YuJianCleanText(content).split(/\r?\n/);
    var output = [];
    var paragraphIndex = 1;

    // 1. 章名段評緩存寫入（供 ruleContent.title 使用）
    if (state.titleComments && summary.chapter > 0 && template) {
      var titleBubble = YuJianTitleBubble(ctx, summary.chapter, ids.bookId, ids.chapterId, template);
      try {
        var src = YuJianSource(ctx);
        if (src && src.put) src.put(String(ids.chapterId), titleBubble);
      } catch (titleErr) {}
    } else {
      try {
        var src2 = YuJianSource(ctx);
        if (src2 && src2.put) src2.put(String(ids.chapterId), '');
      } catch (titleErr2) {}
    }

    // 2. 正文段落評論注入
    for (var index = 0; index < lines.length; index += 1) {
      var line = lines[index];
      var trimmed = line.replace(/^\s+|\s+$/g, '');
      if (!trimmed) continue;
      if (/<img\b/i.test(trimmed)) { output.push(trimmed); continue; }
      var item = summary.counts[String(paragraphIndex)];
      output.push(trimmed + (item && template ? YuJianCommentBubble(ctx, item, ids.bookId, ids.chapterId, paragraphIndex, template) : ''));
      paragraphIndex += 1;
    }

    // 3. 作家說卡片繪製注入
    if (state.authorSay) {
      var authorSay = summary.authorSay;
      if (!authorSay || !authorSay.AuthorComments) {
        var authorName = summary.authorName;
        var authorComments = summary.authorComments;
      }
      if (!authorComments && chapterObj) {
        var ac = chapterObj.AuthorComments || chapterObj.author_comments || chapterObj.authorComments;
        if (typeof ac === 'string') authorComments = ac;
        else if (ac && typeof ac === 'object') authorComments = ac.AuthorComments || ac.content || '';
        if (!authorName && chapterObj.author) authorName = String(chapterObj.author);
      }
      if (authorSay && authorSay.AuthorComments) {
        var authorSayCard = YuJianDrawAuthorSay(ctx, authorSay, 0, ids.bookId, ids.chapterId);
        if (authorSayCard) output.push('', authorSayCard);
      } else if (authorComments) {
        var fallbackAuthorSay = { AuthorName: authorName, AuthorComments: authorComments };
        var fallbackCard = YuJianDrawAuthorSay(ctx, fallbackAuthorSay, 0, ids.bookId, ids.chapterId);
        if (fallbackCard) output.push('', fallbackCard);
      }
    }

    // 4. 本章說匯總卡片繪製注入
    if (state.chapterReview && summary.chapter > 0) {
      var chapterEndCard = YuJianDrawChapterEnd(ctx, summary.chapter, ids.bookId, ids.chapterId, summary.endComments);
      if (chapterEndCard) output.push('', chapterEndCard);
    }

    return output.join('\n');
  } catch (error) {
    try { YuJianBridge(ctx).log('評論注入失敗：' + error); } catch (ignored) {}
    return content;
  }
}

function YuJianContent(result, baseUrl, chapter) {
  var ctx = this || {};
  var response = YuJianParseResult(result);
  if (response.detail) throw new Error(response.detail);
  if (response.message && !response.content) throw new Error(response.message);
  var content = String(response.content || '');
  if (!content) throw new Error('正文內容為空');
  var state = YuJianState(ctx);
  if (!state.comments) {
    return YuJianCleanText(content.replace(/<img\b[^>]*YuJianComment:[^>]*>/gi, ''));
  }
  var ids = {
    bookId: String(response.bookId || response.book_id || ''),
    chapterId: String(response.chapterId || response.chapter_id || '')
  };
  if (!ids.bookId || !ids.chapterId) ids = YuJianCommentContext(baseUrl, chapter);
  var contextUrl = YuJianApiUrl('/book-content', ids);
  return YuJianInjectComments(ctx, content, contextUrl, response);
}

function YuJianContentWithComments(result, baseUrl) {
  return YuJianContent.call(this, result, baseUrl);
}

function YuJianShowCmt(arg1, arg2, arg3, arg4) {
  var ctx, bookId, chapterId, paragraphId;
  if (typeof arg1 === 'object' && arg1 !== null && (arg1.java || arg1.source || arg1.getVariable)) {
    ctx = arg1;
    bookId = arg2;
    chapterId = arg3;
    paragraphId = arg4;
  } else {
    ctx = (typeof this !== 'undefined' && this) || null;
    bookId = arg1;
    chapterId = arg2;
    paragraphId = arg3;
  }

  var bridge = YuJianBridge(ctx);
  var state = YuJianState(ctx);
  var token = YuJianCurrentToken(ctx, state);
  if (!token) token = YuJianCookie(ctx);
  if (!token) token = String(state.readerToken || '');
  var url = 'http://210.16.175.40:11451/comments?bookId=' + encodeURIComponent(String(bookId || '')) +
    '&chapterId=' + encodeURIComponent(String(chapterId || ''));
  if (paragraphId !== null && paragraphId !== undefined && String(paragraphId) !== '') {
    url += '&paragraphId=' + encodeURIComponent(String(paragraphId));
  }
  url += '&token=' + encodeURIComponent(String(token || ''));

  var halfConfig = JSON.stringify({
    state: 4,
    isHideable: true,
    heightPercentage: 0.85,
    expandedCornersRadius: 20,
    dismissOnTouchOutside: true,
    widthPercentage: 1.0,
    maxWidth: -1,
    skipCollapsed: true,
    hardwareAccelerated: true,
    webViewInitialScale: 100
  });

  try {
    if (bridge && bridge.showBrowser) {
      bridge.showBrowser(url, null, null, halfConfig);
    } else if (bridge && bridge.startBrowserAwait) {
      bridge.startBrowserAwait(url, '評論');
    } else if (bridge && bridge.startBrowser) {
      bridge.startBrowser(url, '評論');
    } else if (bridge) {
      bridge.toast('當前閱讀版本不支援內置瀏覽器');
    }
  } catch (error) {
    if (bridge && bridge.startBrowserAwait) {
      try { bridge.startBrowserAwait(url, '評論'); return; } catch (e1) {}
    }
    if (bridge && bridge.startBrowser) {
      try { bridge.startBrowser(url, '評論'); return; } catch (e2) {}
    }
    if (bridge) bridge.toast('無法開啟評論：' + String((error && error.message) || error));
  }
}
;

